const ROLE_BY_NAME = (() => {
  const m = {};
  FOOTBALL_ROLES_SRC.trim().split(/\n|\|/).forEach(x => {
    const t = x.trim();
    const i = t.lastIndexOf(' ');
    if (i > 0) m[t.slice(0, i).toLowerCase()] = ROLE_CODES[t.slice(i + 1)];
  });
  return m;
})();
