function migrateSettings(st) {
  const x = {
    ...(st || {})
  };
  if ((x.rulesV || 0) < 3) {
    if (x.rulePrefs) {
      const p = {
        ...x.rulePrefs
      };
      ['chaos', 'mystery', 'rarity', 'trades'].forEach(k => {
        if (p[k]) p[k] = {
          ...p[k],
          on: false
        };
      });
      x.rulePrefs = p;
    }
    x.rulesV = 3;
  }
  return x;
}
