function migrateTopics(stored) {
  const starters = starterTopics();
  const allIds = starters.map(s => s.id);
  if (!Array.isArray(stored) || !stored.length) {
    store.set(K.seen, allIds);
    return starters;
  }
  const seen = store.get(K.seen, null) || ['t-pl', 't-cf', 't-nba', 't-ff'];
  const out = stored.map(t => {
    const s = starters.find(x => x.id === t.id);
    if (!s) return {
      ...t,
      art: artOf(t),
      folder: folderOf(t)
    };
    if (s.scene && !t.scene) {
      if (t.id === 't-house') {
        const names = t.items.map(i => i.name).sort().join('|');
        return names === OLD_HOUSE_NAMES ? {
          ...s
        } : t;
      }
      t = {
        ...t,
        scene: s.scene
      };
    }
    if ((s.extrasV || 0) > (t.extrasV || 0)) {
      const ids = new Set(t.items.map(i => i.id));
      const names = new Set(t.items.map(i => i.name.toLowerCase()));
      t = {
        ...t,
        extrasV: s.extrasV,
        items: [...t.items, ...s.items.filter(i => /-e\d+$/.test(i.id) && !ids.has(i.id) && !names.has(i.name.toLowerCase()))]
      };
    }
    const byId = {};
    s.items.forEach(i => {
      byId[i.id] = i;
    });
    return {
      ...t,
      era: t.era || s.era,
      battle: t.battle || s.battle,
      sport: t.sport || s.sport,
      art: t.art || s.art,
      folder: t.folder || s.folder,
      kitShape: t.kitShape || s.kitShape,
      kitLabel: t.kitLabel || s.kitLabel,
      photos: t.photos === undefined ? s.photos : t.photos,
      items: t.items.map(i => byId[i.id] && !i.emoji && byId[i.id].emoji ? {
        ...i,
        emoji: byId[i.id].emoji
      } : i)
    };
  });
  starters.forEach(s => {
    if (!seen.includes(s.id) && !out.some(t => t.id === s.id)) out.push(s);
  });
  store.set(K.seen, allIds);
  return out;
}
async function copyText(text) {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch (e) {
    try {
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      const ok = document.execCommand('copy');
      ta.remove();
      return ok;
    } catch (e2) {
      return false;
    }
  }
}
